    "e.g",
    "i.e",
    "etc",
    "vs",
    "Mr",
    "Mrs",
    "Ms",
    "Dr",
    "Sr",
    "Jr",
    "St",
    "Prof",
    "Inc",
    "Co",
    "Ltd",
    "approx",
    "cf",
    "viz",
    "no",
    "v1",
    "v2",
    "v3",
    "v4",
]);
/** Trailing markdown link parenthetical belongs to previous sentence (spec-link-parser.ts). */
const TRAILING_LINK_PARENTHETICAL = /^\(\[[^\]]*\]\(/;
